#include "RelativePolygonComponentData.h"
#include "ArgusLogging.h"
#include "ArgusStaticData.h"

void URelativePolygonComponentData::InstantiateComponentForEntity(ArgusEntity entity) const
{
	RelativePolygonComponent* RelativePolygonComponentRef = entity.GetOrAddComponent<RelativePolygonComponent>();
	ARGUS_RETURN_ON_NULL(RelativePolygonComponentRef, ArgusECSLog);

	RelativePolygonComponentRef->m_relativeUnrealVerticies = m_relativeUnrealVerticies;
	RelativePolygonComponentRef->m_polygonType = m_polygonType;
}

void URelativePolygonComponentData::ReinitializeComponentForEntityPostLoad(ArgusEntity entity) const
{
	RelativePolygonComponent* RelativePolygonComponentRef = entity.GetComponent<RelativePolygonComponent>();
	ARGUS_RETURN_ON_NULL(RelativePolygonComponentRef, ArgusECSLog);

}

void URelativePolygonComponentData::OnComponentDataLoaded() const
{
}

bool URelativePolygonComponentData::MatchesType(const UComponentData* other) const
{
	if (!other)
	{
		return false;
	}

	return other->IsA<URelativePolygonComponentData>();
}
